import{useState}from'react';import{Link,useNavigate}from'react-router-dom';import{Eye,ShieldCheck}from'lucide-react';import{useStore}from'../context/Store';
export default function Auth(){const[email,setEmail]=useState('buyer@example.com');const[pass,setPass]=useState('demo1234');const[err,setErr]=useState('');const{login}=useStore();const nav=useNavigate();return <div className="auth-page"><section className="auth-panel"><Link className="logo" to="/"><b>MERIDIAN</b><span>SUPPLY CO.</span></Link><div><span className="eyebrow">WHOLESALE CUSTOMER PORTAL</span><h1>Welcome back.</h1><p>Sign in to access protected pricing, build orders and manage your wholesale account.</p><form onSubmit={e=>{e.preventDefault();if(!email.includes('@')||pass.length<6)setErr('Enter a valid email and password.');else{login(email);nav('/account')}}}><label>Business email<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<div className="password"><input type="password" value={pass} onChange={e=>setPass(e.target.value)}/><Eye/></div></label>{err&&<p className="form-error">{err}</p>}<div className="remember"><label><input type="checkbox"/> Remember me</label><Link to="/forgot-password">Forgot password?</Link></div><button className="btn dark full">Sign in to your account</button></form><p className="apply-note">Not yet approved? <Link to="/apply">Apply for wholesale access →</Link></p></div><small>This is a frontend demonstration. Any valid email and 6+ character password will sign in.</small></section><section className="auth-image"><div><ShieldCheck/><h2>One account.<br/>A clearer way to buy.</h2><p>Protected pricing, simple reorders and account support in one professional workspace.</p></div></section></div>}
